using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Graph.StarForming;

internal sealed class CoverStabilityDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Combinatorics/Graph/StarForming/CoverStability.";
    private static readonly LibraryNoteRef Source = LibraryNoteRef.Create("D5/L/Certificates/omega2026starformingfamily");
    private static DocumentBlock Node(string name, string title, string text, DescribeRole role) =>
        Describe.Lean(DescribeId.Create(name.Replace('_', '-').Replace('.', '-').ToLowerInvariant()), DeclarationHandle.Create(Prefix + name[(name.LastIndexOf('.') + 1)..]),
            H(title), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(Source),
            Blocks(Paragraph(Text(text))), role);

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The exact test for cover-stable minimality", H("The exact test for cover-stable minimality"),
        Blocks(Paragraph(Text("For each selected deletion, the canonical two-sheeted cover crosses precisely the edges from that vertex to originally unselected vertices. A missing safe certificate makes the lifted selection nonminimal. For a minimal selection in a simple symmetric graph, safe certificates are equivalent to minimality in all its canonical test covers and to preservation in every neighborhood cover. These statements require no global projection-surjectivity convention. They do not by themselves prove the connected-countercover strengthening.")),
            Node("Crossed", "Crossed", "Exact declaration: def Crossed {Vertex : Type} (selection : Vertex → Prop) (deleted first second : Vertex) : Prop.", DescribeRole.Definition),
            Node("CanonicalAdj", "CanonicalAdj", "Exact declaration: def CanonicalAdj {Vertex : Type} (adjacency : Vertex → Vertex → Prop) (selection : Vertex → Prop) (deleted : Vertex) (first second : Vertex × Bool) : Prop.", DescribeRole.Definition),
            Node("canonical_symmetric", "canonical symmetric", "Exact declaration: theorem canonical_symmetric {Vertex : Type} {adjacency : Vertex → Vertex → Prop} {selection : Vertex → Prop} (deleted : Vertex) (hsymmetric : ∀ first second, adjacency first second → adjacency second first) : ∀ first second, CanonicalAdj adjacency selection deleted first second → CanonicalAdj adjacency selection deleted second first.", DescribeRole.Theorem),
            Node("canonical_cover", "canonical cover", "Exact declaration: theorem canonical_cover {Vertex : Type} {adjacency : Vertex → Vertex → Prop} {selection : Vertex → Prop} (deleted : Vertex) : NeighborhoodCover adjacency (CanonicalAdj adjacency selection deleted) Prod.fst.", DescribeRole.Theorem),
            Node("canonical_selected_edge", "canonical selected edge", "Exact declaration: theorem canonical_selected_edge {Vertex : Type} {adjacency : Vertex → Vertex → Prop} {selection : Vertex → Prop} (deleted first second : Vertex) (sheet : Bool) (hfirst : selection first) (hsecond : selection second) (hedge : adjacency first second) : CanonicalAdj adjacency selection deleted (first, sheet) (second, sheet).", DescribeRole.Theorem),
            Node("canonical_retained_edge", "canonical retained edge", "Exact declaration: theorem canonical_retained_edge {Vertex : Type} {adjacency : Vertex → Vertex → Prop} {selection : Vertex → Prop} (deleted outside selected : Vertex) (sheet : Bool) (hselected : selection selected) (hdifferent : selected ≠ deleted) (hedge : adjacency outside selected) : CanonicalAdj adjacency selection deleted (outside, sheet) (selected, sheet).", DescribeRole.Theorem),
            Node("twoAt_canonical_after_deletion", "twoAt canonical after deletion", "Exact declaration: theorem twoAt_canonical_after_deletion {Vertex : Type} {adjacency : Vertex → Vertex → Prop} {selection : Vertex → Prop} (deleted outside : Vertex) (sheet : Bool) (hstar : TwoAt adjacency (fun vertex => selection vertex ∧ vertex ≠ deleted) outside) : TwoAt (CanonicalAdj adjacency selection deleted) (fun vertex => selection vertex.1 ∧ vertex ≠ (deleted, false)) (outside, sheet).", DescribeRole.Theorem),
            Node("canonical_deletion_forms_of_missing_certificate", "canonical deletion forms of missing certificate", "Exact declaration: theorem canonical_deletion_forms_of_missing_certificate {Vertex : Type} {adjacency : Vertex → Vertex → Prop} {selection : Vertex → Prop} (hirreflexive : ∀ vertex, ¬ adjacency vertex vertex) (hsymmetric : ∀ first second, adjacency first second → adjacency second first) (deleted : Vertex) (hselected : selection deleted) (hmissing : ¬ ((¬ TwoAt adjacency (fun vertex => selection vertex ∧ vertex ≠ deleted) deleted) ∨ ∃ outside, SafeFailure adjacency selection deleted outside)) : Forms (CanonicalAdj adjacency selection deleted) (fun vertex => selection vertex.1 ∧ vertex ≠ (deleted, false)).", DescribeRole.Theorem),
            Node("canonical_nonminimal_of_missing_certificate", "canonical nonminimal of missing certificate", "Exact declaration: theorem canonical_nonminimal_of_missing_certificate {Vertex : Type} {adjacency : Vertex → Vertex → Prop} {selection : Vertex → Prop} (hirreflexive : ∀ vertex, ¬ adjacency vertex vertex) (hsymmetric : ∀ first second, adjacency first second → adjacency second first) (deleted : Vertex) (hselected : selection deleted) (hmissing : ¬ ((¬ TwoAt adjacency (fun vertex => selection vertex ∧ vertex ≠ deleted) deleted) ∨ ∃ outside, SafeFailure adjacency selection deleted outside)) : ¬ Minimal (CanonicalAdj adjacency selection deleted) (fun vertex => selection vertex.1).", DescribeRole.Theorem),
            Node("safe_certificates_iff_canonical_minimal", "safe certificates iff canonical minimal", "Exact declaration: theorem safe_certificates_iff_canonical_minimal {Vertex : Type} {adjacency : Vertex → Vertex → Prop} {selection : Vertex → Prop} (hirreflexive : ∀ vertex, ¬ adjacency vertex vertex) (hsymmetric : ∀ first second, adjacency first second → adjacency second first) (hminimal : Minimal adjacency selection) : HasSafeCertificates adjacency selection ↔ ∀ deleted, selection deleted → Minimal (CanonicalAdj adjacency selection deleted) (fun vertex => selection vertex.1).", DescribeRole.Theorem),
            Node("safe_certificates_iff_all_covers", "safe certificates iff all covers", "Exact declaration: theorem safe_certificates_iff_all_covers {Vertex : Type} {adjacency : Vertex → Vertex → Prop} {selection : Vertex → Prop} (hirreflexive : ∀ vertex, ¬ adjacency vertex vertex) (hsymmetric : ∀ first second, adjacency first second → adjacency second first) (hminimal : Minimal adjacency selection) : HasSafeCertificates adjacency selection ↔ ∀ (Lift : Type) (liftAdjacency : Lift → Lift → Prop) (projection : Lift → Vertex), NeighborhoodCover adjacency liftAdjacency projection → (∀ first second, liftAdjacency first second → liftAdjacency second first) → Minimal liftAdjacency (fun vertex => selection (projection vertex)).", DescribeRole.Theorem)), []));
}
